import{_ as t,o,c as d,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Application UI Screenshots & SRS Screen Evidence (D15 – D19)","description":"","frontmatter":{},"headers":[],"relativePath":"screenshots/README.md","filePath":"screenshots/README.md"}'),c={name:"screenshots/README.md"};function a(r,e,i,s,l,g){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="application-ui-screenshots-srs-screen-evidence-d15-–-d19" tabindex="-1">Application UI Screenshots &amp; SRS Screen Evidence (<code>D15</code> – <code>D19</code>) <a class="header-anchor" href="#application-ui-screenshots-srs-screen-evidence-d15-–-d19" aria-label="Permalink to &quot;Application UI Screenshots &amp; SRS Screen Evidence (`D15` – `D19`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../wireframe/README.html">Wireframes &amp; UI Architecture</a> · <a href="./../ba/README.html">BA Specifications</a> · <a href="./../feature/README.html">Feature Specifications</a></p><p>This directory archives <strong>136 verified production UI screenshots</strong> organized across 5 milestone deliverable batches (<code>D15</code> through <code>D19</code>), capturing the live <code>brandhub-web</code> (React <code>19.2</code> + Tailwind CSS <code>4.3</code>) and <code>brandhub-mobile-app</code> (Expo SDK <code>58</code> / React Native <code>0.88</code>) interfaces used as visual evidence in <strong>Report 3 — SRS (<code>brandhub-final_report/report3/report3_official.docx</code>)</strong>.</p><hr><h2 id="_1-deliverable-batch-inventory-136-pngs" tabindex="-1">1. Deliverable Batch Inventory (<code>136</code> PNGs) <a class="header-anchor" href="#_1-deliverable-batch-inventory-136-pngs" aria-label="Permalink to &quot;1. Deliverable Batch Inventory (`136` PNGs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Batch Folder</th><th style="text-align:left;">File Range on Disk</th><th style="text-align:center;">PNG Count</th><th style="text-align:left;">SRS Domain &amp; Epic Coverage</th></tr></thead><tbody><tr><td style="text-align:left;"><code>D15/</code></td><td style="text-align:left;"><code>DA-D15-01.png</code> – <code>DA-D15-27.png</code> <em>(excluding <code>DA-D15-10</code>)</em></td><td style="text-align:center;"><strong>26</strong></td><td style="text-align:left;"><strong><code>3.2</code> Authentication &amp; Authorization</strong> (<code>Sign Up</code>, <code>Sign In</code>, Google OAuth, <code>Reset/Change Password</code>, <code>OTP</code>, <code>2FA TOTP</code>), <strong><code>3.3</code> User &amp; Client Profile</strong>, and <strong><code>3.4</code> Agency &amp; Workspace</strong> (<code>Agency List/Dashboard</code>, Invitations, Workspace Settings, Templates, Members)</td></tr><tr><td style="text-align:left;"><code>D16/</code></td><td style="text-align:left;"><code>DA-D16-01.png</code> – <code>DA-D16-26.png</code></td><td style="text-align:center;"><strong>26</strong></td><td style="text-align:left;"><strong><code>3.5</code> Media Package &amp; Media Campaign</strong> (<code>Template Packages</code>, 2-Party Negotiation, <code>CampaignTimelineGrid</code>, <code>Content Requests</code>) and <strong><code>3.6</code> Content &amp; Workflow</strong> (<code>List</code>, <code>Calendar</code>, <code>Gantt</code>, <code>Kanban</code>, 3-Tier <code>Approval Sequence</code>, <code>TaskSection</code> Unicode Editor, Material Repository, Google Drive Sync, Watermark, Hashtags, Surveys, Mail Templates, Realtime Chat)</td></tr><tr><td style="text-align:left;"><code>D17/</code></td><td style="text-align:left;"><code>DA-D17-01.png</code> – <code>DA-D17-28.png</code></td><td style="text-align:center;"><strong>28</strong></td><td style="text-align:left;"><strong><code>3.7</code> AI Features</strong>: Vietnam Trend Suggestions, Interactive <code>Neo4j Trend Knowledge Graph</code>, Brand Knowledge RAG Upload/Index Status, AI Caption Generator &amp; Variants, Virtual Brand Ambassador, Commercial Image Studio, Wan 2.2 VACE Product Video Studio, and Third-Party Collaborator Directory / AI Recommendation</td></tr><tr><td style="text-align:left;"><code>D18/</code></td><td style="text-align:left;"><code>DA-D18-01.png</code> – <code>DA-D18-33.png</code></td><td style="text-align:center;"><strong>33</strong></td><td style="text-align:left;"><strong><code>3.8</code> Publishing &amp; Social</strong> (OAuth Account Connect, Desktop/Mobile Mockup Previews, Scheduling, Queue/DLQ Tracking, and Publishing across <strong>Facebook, Instagram, TikTok, Threads</strong>) + <strong><code>3.9</code> Subscription &amp; Billing</strong> (<code>STUDIO_*</code> / <code>BASIC..ENTERPRISE</code> Upgrade Plans, <strong>SePay VietQR</strong> Checkout, Invoices, <code>agency_credit_wallets</code>, and Workspace Credit Caps)</td></tr><tr><td style="text-align:left;"><code>D19/</code></td><td style="text-align:left;"><code>DA-D19-01.png</code> – <code>DA-D19-23.png</code></td><td style="text-align:center;"><strong>23</strong></td><td style="text-align:left;"><strong><code>3.10</code> Admin Functions</strong> (<code>Push Notification</code>, <code>Platform Statistics</code>, 5-Host <code>System Health Monitoring</code>, <code>Content Moderation Queue</code>, <code>User Directory &amp; Violation Strikes</code>, <code>AI Credit Price List &amp; CSV Import</code>, <code>SePay Revenue Dashboard</code>, <code>PDF Report Export</code>) + <strong><code>brandhub-mobile-app</code></strong> companion screens (<code>DA-D19-16</code>–<code>DA-D19-21</code>)</td></tr><tr><td style="text-align:left;"><strong>Total</strong></td><td style="text-align:left;"><strong><code>DA-D15</code> – <code>DA-D19</code></strong></td><td style="text-align:center;"><strong>136 PNGs</strong></td><td style="text-align:left;">Complete visual baseline across all 9 SRS domains</td></tr></tbody></table><hr><h2 id="_2-non-ui-deliverable-ids-backfill-verification-ledger" tabindex="-1">2. Non-UI Deliverable IDs &amp; Backfill Verification Ledger <a class="header-anchor" href="#_2-non-ui-deliverable-ids-backfill-verification-ledger" aria-label="Permalink to &quot;2. Non-UI Deliverable IDs &amp; Backfill Verification Ledger&quot;">​</a></h2><p>Across the <code>DA-D15</code>–<code>DA-D19</code> numbering sequence (<code>137</code> allocated deliverable slots), <strong>136 PNGs</strong> exist on disk and exactly <strong>1 ID (<code>DA-D15-10</code>)</strong> intentionally has no screenshot because it represents a headless backend-only token endpoint:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Deliverable ID</th><th style="text-align:center;">Disk Status</th><th style="text-align:left;">Verification / Architectural Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>DA-D15-10</code></strong></td><td style="text-align:center;"><strong>No PNG (Expected)</strong></td><td style="text-align:left;">Headless backend JWT Refresh Token rotation endpoint (<code>POST /api/v1/auth/refresh</code> with HttpOnly cookie + Redis <code>jwt:blacklist:{jti}</code>) — zero standalone UI screen.</td></tr><tr><td style="text-align:left;"><code>DA-D15-23</code>, <code>DA-D15-27</code></td><td style="text-align:center;"><strong>Present</strong> (<code>D15/</code>)</td><td style="text-align:left;">Verified multi-tenant workspace isolation &amp; permission guard screens.</td></tr><tr><td style="text-align:left;"><code>DA-D17-05</code>, <code>DA-D17-21</code>, <code>DA-D17-22</code></td><td style="text-align:center;"><strong>Present</strong> (<code>D17/</code>)</td><td style="text-align:left;">Verified Brand Knowledge RAG document chunking/indexing status &amp; semantic preview screens.</td></tr><tr><td style="text-align:left;"><code>DA-D18-25</code>, <code>DA-D18-26</code></td><td style="text-align:center;"><strong>Present</strong> (<code>D18/</code>)</td><td style="text-align:left;">Verified RabbitMQ Publishing Queue Retry (<code>1m</code> / <code>5m</code> / <code>15m</code>) &amp; Dead-Letter Queue (<code>DLQ</code>) status UI at <code>/workspaces/:id/publishing/queue</code>.</td></tr><tr><td style="text-align:left;"><code>DA-D19-16</code> – <code>DA-D19-21</code></td><td style="text-align:center;"><strong>Present</strong> (<code>D19/</code>)</td><td style="text-align:left;">Verified <code>brandhub-mobile-app</code> (Expo 58) companion captures for mobile approval, notifications, calendar, and post preview.</td></tr></tbody></table><hr><h2 id="_3-srs-report-3-report3-official-docx-integration-standards" tabindex="-1">3. SRS Report 3 (<code>report3_official.docx</code>) Integration Standards <a class="header-anchor" href="#_3-srs-report-3-report3-official-docx-integration-standards" aria-label="Permalink to &quot;3. SRS Report 3 (`report3_official.docx`) Integration Standards&quot;">​</a></h2><p>When capturing or updating screenshots for SRS <code>Screen Layout</code> subsections (see <a href="./../guides/team-workflow-guide.html">Team Workflow Guide</a>):</p><ol><li><strong>Sequential Captioning</strong>: Every embedded <code>Screen Layout</code> image in <code>brandhub-final_report/report3/report3_official.docx</code> MUST carry a centered italic caption <code>Figure X - &lt;Function Name&gt;</code> numbered sequentially (<code>Figure 1</code>–<code>Figure 150</code>).</li><li><strong>Canonical Terminology in UI</strong>: Captured screens must display only the <strong>6 canonical roles</strong> (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), the <strong>4 supported social platforms</strong> (<strong>Facebook, Instagram, TikTok, Threads</strong>), and <strong>SePay (VietQR)</strong> for billing checkouts.</li><li><strong>Theme &amp; Locale Consistency</strong>: Capture clean <code>1440px</code> desktop viewports (<code>375px</code>/<code>390px</code> for mobile views) with complete <code>i18next</code> (<code>vi</code>/<code>en</code>) translations and zero raw translation keys or placeholder stack traces.</li></ol>',14)])])}const D=t(c,[["render",a]]);export{h as __pageData,D as default};
